    text: 'What is a "spin lock" and when is it appropriate to use one?',
    options: ['A type of deadlock where processes loop indefinitely', 'A busy-wait lock where a thread continuously checks if the lock is free; appropriate when the expected wait time is shorter than a context switch', 'A lock that prevents CPU context switches', 'A lock used exclusively in RTOS systems'],
    answer: 'A busy-wait lock where a thread continuously checks if the lock is free; appropriate when the expected wait time is shorter than a context switch',
    explanation: 'A spin lock wastes CPU cycles while waiting ("spinning"). Unlike a semaphore that blocks and yields the CPU, spinning avoids expensive context switches. Appropriate on multicore systems for very short critical sections where blocking would waste more time.',
